      tw: "AO3（Archive of Our Own）是同人作品存檔站，由非營利組織 Organization for Transformative Works（OTW）運營，靠捐贈維持、志願者維護，站內沒有廣告，閱讀與釋出都不收費。小說、漫畫、音影片等各類同人作品都能釋出與檢索，它的標籤系統是招牌：作品按原作、角色、配對、題材與分級打標，讀者可以多條件組合篩選，也可以反過來排除不想看的標籤；支援把作品下載為 EPUB、MOBI、PDF、HTML 等格式離線看，也支援系列與合集整理。收錄提醒：註冊賬號需要排隊等邀請（訪客可以直接閱讀大部分公開作品）；站內創作自由度很高，內容良莠不齊，靠分級與警告標籤自行把關；介面以英文為主，但中文等各語言作品都很多。",
