      en: "Wikipedia is a free encyclopedia in hundreds of languages, hosted by the Wikimedia Foundation and written by volunteers worldwide. Every article is free to read, and anyone who registers can edit. It is split into language editions (Chinese, English and many more), with the English edition the largest; each article keeps a revision history and a talk page, and sources are listed as references at the end, so you can follow them to verify a fact yourself. Our link points to its official multilingual portal, www.wikipedia.org, where you pick a language first. Listing notes: an encyclopedia is a secondary compilation — a good starting point for a topic, not the final word. For anything important, follow the citations to primary sources; articles under heavy editorial dispute usually carry a notice at the top.",
      tw: "維基百科是多語言的自由百科全書，由維基媒體基金會託管、全球志願者共同編寫，條目向所有人免費開放閱讀，註冊後也可以參與編輯。它按語言分版（中文、英文等數百個語言版本），內容量以英文版為最大；每個條目都有修訂歷史與討論頁，出處以文末參考文獻的形式給出，查資料時可以順著來源繼續核實。本站入口是它的官方多語言門戶 www.wikipedia.org，可以先選語言再進對應版本。收錄提醒：百科是二手彙編，適合當作瞭解一個主題的起點而不是最終依據；重要事實請順著條目的引用去查一手來源，編輯爭議較大的條目，頁面頂部通常會有提示。",
