      en: "Bingdu Bar ('Virus Bar') is a long-running community on Baidu Tieba with a one-of-a-kind game: members pretend, in perfect deadpan, to discuss entirely fictional computer viruses — inventing names, symptoms and 'cures' for malware that does not exist, with the most absurd posts becoming the most beloved. It is a landmark of Tieba's parody culture, years old, with a deep backlog of reader-created joke threads; even its forum rules are written like a genuine virus-prevention document, which is part of the joke. We list it under internet slang in the leisure group as a specimen of Chinese internet humour. Listing notes: this is pure entertainment — the 'virus knowledge' inside is all made up, so never treat it as real computer help; and some old threads' images have expired.",
