    image: "/tools/awesome-prompts.webp",
    oneLiner: { zh: "GitHub 上的开源提示词合集：现成的角色模板，复制改改就能用。", en: "An open-source prompt collection on GitHub: ready-made role templates to copy and adapt.",
    tw: "GitHub 上的開源提示詞合集：現成的角色模板，複製改改就能用。" },
    detail: { zh: "GitHub 上的知名开源仓库 awesome-chatgpt-prompts（现也以 Prompts Chat 名义运营），由社区持续贡献现成提示词：扮演面试官、翻译、编剧、顾问等角色型模板和各类任务模板，可在官网 prompts.chat 在线浏览搜索，也能整库自托管部署。星标数 17 万以上（2026-11 核实时约 175,764）。许可证是双轨：仓库代码为 MIT，提示词内容数据（prompts.csv、PROMPTS.md 与用户投稿）为 CC0 1.0，取用自由度高。写好的提示词不绑定单一模型，ChatGPT、Claude、Gemini 等主流对话模型都能用。", en: "The well-known GitHub repository awesome-chatgpt-prompts (now also run as Prompts Chat) collects community-contributed prompts: role templates — interviewer, translator, screenwriter, consultant and many more — plus task templates of all kinds. Browse and search them online at prompts.chat, or self-host the whole library. It has over 170,000 stars (about 175,764 when checked in November 2026). Licensing is dual-track: the repository code is MIT, while the prompt content data (prompts.csv, PROMPTS.md and user submissions) is CC0 1.0, so the prompts themselves are about as free to reuse as it gets. The prompts are not tied to one model — they work with ChatGPT, Claude, Gemini and other mainstream chat models.",
    tw: "GitHub 上的知名開源倉庫 awesome-chatgpt-prompts（現也以 Prompts Chat 名義運營），由社群持續貢獻現成提示詞：扮演面試官、翻譯、編劇、顧問等角色型模板和各類任務模板，可在官網 prompts.chat 線上瀏覽搜尋，也能整庫自託管部署。星標數 17 萬以上（2026-11 核實時約 175,764）。許可證是雙軌：倉庫程式碼為 MIT，提示詞內容資料（prompts.csv、PROMPTS.md 與使用者投稿）為 CC0 1.0，取用自由度高。寫好的提示詞不繫結單一模型，ChatGPT、Claude、Gemini 等主流對話模型都能用。" },
    audience: { zh: "天天用 AI 对话工具、但懒得从零琢磨提示词的人；也适合想批量找写作、编程、营销类提示词模板的内容工作者。", en: "People who use AI chat tools daily but dislike writing prompts from scratch — and content workers who want writing, coding and marketing prompt templates in bulk.",
    tw: "天天用 AI 對話工具、但懶得從零琢磨提示詞的人；也適合想批次找寫作、程式設計、營銷類提示詞模板的內容工作者。" },
    take: { zh: "适合当灵感库和起手模板：量大、免费、授权干净（内容 CC0）。实话实说，合集质量参差，热门条目有些年头，直接套用效果一般，挑到合适的再按自己的场景改一遍，出活率会高很多。", en: "Best used as an idea bank and starting templates: huge, free, and cleanly licensed (CC0 content). Honestly, quality varies and some popular entries are dated — pick a close match and adapt it to your scenario rather than pasting blindly.",
    tw: "適合當靈感庫和起手模板：量大、免費、授權乾淨（內容 CC0）。實話實說，合集質量參差，熱門條目有些年頭，直接套用效果一般，挑到合適的再按自己的場景改一遍，出活率會高很多。" },
