    oneLiner: { zh: "用户上传的高清壁纸站：一百三十多万张，按分辨率细筛。", en: "A user-uploaded wallpaper site: 1.3M+ wallpapers with fine-grained resolution filters.",
    tw: "使用者上傳的高畫質桌布站：一百三十多萬張，按解析度細篩。" },
    detail: { zh: "社区用户上传的壁纸站，官网统计壁纸约 1,328,338 张、注册用户约 175 万（2026-11 核实）。强项是筛选：可按分类、标签、分辨率、宽高比和颜色找图，还有热门与最新排行，找 4K 与超宽屏壁纸很方便。口径如实：内容由用户上传，版权归原作者，定位是个人更换壁纸使用，不等于可商用素材库；站方明文禁止 AI 生成图上传。站内有成人分级内容，默认过滤，登录后可在设置里调整。", en: "A community wallpaper site built on user uploads; its own counters list about 1,328,338 wallpapers and roughly 1.75 million registered users (checked November 2026). Its strength is filtering — by category, tag, resolution, aspect ratio and even colour — plus toplist and latest rankings, which makes hunting 4K and ultrawide wallpapers easy. Stated plainly: content is user-uploaded and copyright stays with the original creators; the site is for personal wallpaper use, not a cleared commercial asset library. The site explicitly bans AI-generated uploads. Adult-rated content exists, is filtered by default, and can be adjusted in settings after logging in.",
    tw: "社群使用者上傳的桌布站，官網統計桌布約 1,328,338 張、註冊使用者約 175 萬（2026-11 核實）。強項是篩選：可按分類、標籤、解析度、寬高比和顏色找圖，還有熱門與最新排行，找 4K 與超寬屏桌布很方便。口徑如實：內容由使用者上傳，版權歸原作者，定位是個人更換桌布使用，不等於可商用素材庫；站方明文禁止 AI 生成圖上傳。站內有成人分級內容，預設過濾，登入後可在設定裡調整。" },
    audience: { zh: "爱折腾桌面和手机壁纸的人，尤其是用高分屏、带鱼屏，想按确切分辨率找图的用户。", en: "People who enjoy changing desktop and phone wallpapers — especially owners of high-resolution or ultrawide screens who need exact sizes.",
    tw: "愛折騰桌面和手機桌布的人，尤其是用高分屏、帶魚屏，想按確切解析度找圖的使用者。" },
    take: { zh: "适合找壁纸：量大、筛选是真好用，按颜色找图这种细节别家少有。但别把它当商用图库——版权不在站方手里，拿去做商业项目出了问题只能自己担。", en: "Great for wallpaper hunting: huge volume and genuinely best-in-class filters, including search by colour. Do not treat it as a commercial asset library, though — the site does not hold the rights to what users uploaded, so commercial reuse is at your own risk.",
    tw: "適合找桌布：量大、篩選是真好用，按顏色找圖這種細節別家少有。但別把它當商用相簿——版權不在站方手裡，拿去做商業專案出了問題只能自己擔。" },
